','d218993e-e841-4ec5-99f5-7b22a86e3daa','d31159e2-e4c5-46d8-92ae-d2939f8fdbe3','d373d24d-b5dd-4ac0-b978-730fd138e3aa','d50eddca-72da-4aba-b1ab-94e62b517316','d59be0f7-ad8d-47cf-ae3e-bc493d443673','d61a1be8-8103-4b04-8c28-7d4cb4fcce1f','d6367ae5-21f8-424a-9de8-de17a42a1ed2','d940090b-c191-4f02-8737-63e05142a073','d9da4d21-9c0d-4aa9-8693-69bee3fb358d','dd3f9872-52be-48f4-93fb-e6288a3f0d14','de220364-519f-4054-9363-4b4c1bf06c5a','dfbba5f8-326c-45c7-b6c4-56cef0a5e501','e3561ccb-a021-4e33-b25a-1adc50d6ab88','e3c7cbb8-218a-4cdd-9651-05c4a6a0d263','e3e3570f-bf37-42dd-856e-e26ed9895b34','e433aff7-3377-4a08-98db-7a91190ea50f','e4e0338d-a106-4449-b96a-177293951f7d','e7a857f6-dd7b-468b-b032-dbedc589e7da','e8e5b763-22dd-4eb5-8dd8-6ec314dedae9','ea0dfb97-2329-4439-acf6-fa5c754852ef','ea5ddaa9-688c-46cc-b76c-3f05205efa12','ecb13294-f77e-40a0-b801-e0798ce289d8','ee53dc67-1d59-4439-9b2d-9494c30c04bd','ee931067-e8fe-4edc-aa01-e45137a6a56e','eeeb635b-c43a-4cc8-b2c4-d85c78787a6a','f053c8b7-f6ce-44d6-9405-f5d12b39b47b','f40302ab-dfca-4757-a5e9-0a527f13a9ce','f8e12ed1-9187-4878-b725-abe39a59cd7b','f98f2608-703d-4394-af0a-fc9962055fba','f9cb831d-3d32-4c52-b5a5-9a3d04e0f0c1','fadbfb95-56aa-4d00-a6c7-f64c823371b0','fb71c742-65f0-4fa4-97c2-b778d5d8dd8e','fc2a4792-02d4-4980-80d9-644adb6b22a0','fce7f617-e479-4738-aaeb-b74b063d0764','fd5b8c43-0ca7-4c1b-8fd8-5e87f6237437','fea2f152-7d9e-4b45-8ae8-274350a27d83','fff9f5a7-9642-4767-a1e8-c94ca618c9b8']::uuid[];
  v_count integer;
  v_amount numeric;
  v_id uuid;
  v_value numeric;
  v_r jsonb;
  v_n integer:=0;
  v_sum numeric:=0;
  v_ids uuid[]:=ARRAY[]::uuid[];
BEGIN
  IF to_regprocedure('public.fn_ca_pay_closed_target_ticket_in_cash(uuid,text)') IS NULL THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_DOOR_MISSING: apply 20261012054804 first';
  END IF;
  SELECT count(*), COALESCE(sum(tk.value),0) INTO v_count,v_amount
    FROM public.tournament_tickets tk WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-12 19:00:00+00' AND tk.created_at<'2026-09-17 21:45:00+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id);
  IF v_count<>190 OR v_amount<>7730.00 THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_PREIMAGE_CHANGED: part 2 has % tickets worth %',v_count,v_amount;
  END IF;
  FOR v_id,v_value IN
    SELECT tk.id,tk.value FROM public.tournament_tickets tk
     WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-12 19:00:00+00' AND tk.created_at<'2026-09-17 21:45:00+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id)
     ORDER BY tk.created_at,tk.id
  LOOP
    v_r:=public.fn_ca_pay_closed_target_ticket_in_cash(v_id,'stranded_ticket_settlement_20261012');
    IF COALESCE((v_r->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_r->>'replayed')::boolean,false)
       OR (v_r->>'amount')::numeric IS DISTINCT FROM v_value THEN
      RAISE EXCEPTION 'STRANDED_TICKET_CASH_REFUSED: %',v_r;
    END IF;
    v_n:=v_n+1;
    v_sum:=round(v_sum+v_value,2);
    v_ids:=v_ids||v_id;
  END LOOP;
  IF v_n<>190 OR v_sum<>7730.00 THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_RESULT_CHANGED: paid % tickets worth %',v_n,v_sum;
  END IF;
  IF (SELECT count(*) FROM public.tournament_tickets tk
       WHERE tk.id=ANY(v_ids) AND tk.status='redeemed'
         AND tk.redeemed_at=transaction_timestamp())<>v_n
     OR (SELECT COALESCE(sum(l.amount),0)
           FROM public.chip_ledger_idem i JOIN public.chip_ledger l ON l.id=i.leg_id
          WHERE i.idempotency_key IN (
            SELECT 'ticket:'||x::text||':closed-target-cash' FROM unnest(v_ids) x)
            AND l.from_type='escrow' AND l.to_type='player_wallet'
            AND l.category='ticket_redeem')<>v_sum
     OR EXISTS (SELECT 1 FROM public.tournament_tickets tk WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-12 19:00:00+00' AND tk.created_at<'2026-09-17 21:45:00+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id)) THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_RESULT_CHANGED: receipts disagree for % tickets worth %',v_n,v_sum;
  END IF;
  RAISE NOTICE 'stranded satellite tickets paid in cash, part 2: % tickets worth %',v_n,v_sum;
END
$settle$;
COMMIT;
